#!/usr/bin/env bash
# Docs : partie « Données » (Prisma) en 6 chapitres — tutoriel d'origine restauré, découpé, réécrit sur le
# noyau réel (membres, sessions, groupes) ; diagrammes redessinés ; remplace donnees/modeliser-avec-prisma.mdx.
# Code : type de session tiré de Prisma (SessionGetPayload), commentaires périmés corrigés.
# Prérequis : apply-auth-regles-partagees.sh.
# Usage (racine du repo) : bash apply-docs-donnees-prisma.sh
set -euo pipefail
cd "$(dirname "$0")"
[ -f pnpm-workspace.yaml ] || { echo "À lancer à la racine du repo."; exit 1; }

if git show HEAD:"apps/web/content/docs/dev/donnees/pourquoi-le-modele.mdx" 2>/dev/null | grep -qF "Pourquoi tout commence par le modèle"; then echo "Déjà appliqué (commité)."; exit 0; fi
grep -qF "export const PASSWORD_MIN_LENGTH" "packages/contracts/src/auth/auth.schema.ts" 2>/dev/null || { echo "❌ lancer d'abord apply-auth-regles-partagees.sh"; exit 1; }
MODIFIED=("packages/backend/src/modules/auth/getSessionFromRequest.ts" "packages/backend/src/modules/memberGroups/ensureAdminGroup.service.ts" "apps/web/content/docs/dev/index.mdx" "apps/web/src/features/docs/diagrams/PrismaCoreErdDiagram.tsx" "apps/web/src/features/docs/diagrams/PrismaCoreMemoryDiagram.tsx")
CREATED=("apps/web/content/docs/dev/donnees/pourquoi-le-modele.mdx" "apps/web/content/docs/dev/donnees/lire-le-schema.mdx" "apps/web/content/docs/dev/donnees/le-noyau-du-modele.mdx" "apps/web/content/docs/dev/donnees/les-relations.mdx" "apps/web/content/docs/dev/donnees/le-modele-executable.mdx" "apps/web/content/docs/dev/donnees/ecrire-et-faire-evoluer.mdx")
restore(){ git checkout -q -- "${MODIFIED[@]}" 2>/dev/null || true; rm -f "${CREATED[@]}"; echo "  ↩ fichiers restaurés"; }
if grep -qF "Pourquoi tout commence par le modèle" "apps/web/content/docs/dev/donnees/pourquoi-le-modele.mdx" 2>/dev/null; then echo "  restes d'un essai précédent non commité → nettoyage"; restore; fi
trap 'restore' ERR

mkdir -p "apps/web/src/features/docs/diagrams"
